package com.kaymlyn.planeteater.simulation.physics;

import com.kaymlyn.planeteater.simulation.physics.Vector3D;

/**
 * Represents a scheduled velocity change at a specific time.
 *
 * This is the fundamental unit of spacecraft maneuvering - a planned
 * delta-V to be executed at a specific simulation time. Position tracking
 * is handled by the n-body simulation, not pre-calculated.
 *
 * A burn consists of:
 * - When to execute (absolute simulation time)
 * - How much to change velocity (delta-V vector)
 * - Optional description for logging/UI
 *
 * Generated by Claude (Sonnet 4.5)
 */
public record ScheduledBurn(
        String id,
        double executionTime,      // Absolute simulation time (seconds since epoch)
        Vector3D deltaVelocity,    // Velocity change to apply (m/s)
        String description         // Human-readable label (e.g., "Hohmann Departure")
) implements Comparable<ScheduledBurn> {

    /**
     * Natural ordering by execution time (earliest first).
     */
    @Override
    public int compareTo(ScheduledBurn other) {
        return Double.compare(this.executionTime, other.executionTime);
    }

    /**
     * Calculate fuel mass required for this burn using Tsiolkovsky equation.
     *
     * @param currentMass Total mass of spacecraft before burn (kg)
     * @param exhaustVelocity Effective exhaust velocity of propulsion system (m/s)
     * @return Fuel mass consumed by this burn (kg)
     */
    public double fuelRequired(double currentMass, double exhaustVelocity) {
        double deltaVMagnitude = deltaVelocity.magnitude();
        // m_fuel = m_initial * (1 - e^(-Δv/v_e))
        return currentMass * (1 - Math.exp(-deltaVMagnitude / exhaustVelocity));
    }

    /**
     * Get the delta-V magnitude (total velocity change).
     *
     * @return Delta-V in m/s
     */
    public double deltaVMagnitude() {
        return deltaVelocity.magnitude();
    }

    /**
     * Check if this burn should execute at the given time.
     * Uses small tolerance to account for discrete time steps.
     *
     * @param currentTime Current simulation time
     * @param tolerance Time tolerance in seconds (default: 1.0 second)
     * @return true if burn should execute now
     */
    public boolean shouldExecute(double currentTime, double tolerance) {
        return Math.abs(executionTime - currentTime) <= tolerance;
    }

    /**
     * Check if this burn should execute at the given time (1 second tolerance).
     */
    public boolean shouldExecute(double currentTime) {
        return shouldExecute(currentTime, 1.0);
    }

    @Override
    public String toString() {
        return String.format("ScheduledBurn[%s at t=%.1f, Δv=%.1f m/s, '%s']",
                id, executionTime, deltaVMagnitude(), description);
    }
}